function incremovableSubarrayCount(nums) {
  const n = nums.length;
  let count = 0;

  for (let start = 0; start < n; start++) {
    for (let end = start; end < n; end++) {
      let previous = -Infinity;
      let increasing = true;
      for (let k = 0; k < n; k++) {
        if (k >= start && k <= end) {
          continue;
        }
        if (nums[k] <= previous) {
          increasing = false;
          break;
        }
        previous = nums[k];
      }
      if (increasing) {
        count++;
      }
    }
  }
  return count;
}

