function incremovableSubarrayCount(nums) {
  let total = 0;
  for (let i = 0; i < nums.length; i++)
    for (let j = i + 1; j <= nums.length; j++) {
      const rest = nums.slice(0, i).concat(nums.slice(j));
      if (rest.every((v, k) => k === 0 || rest[k - 1] < v)) total++;
