function generate(rand, size) {
  const n = size === 'large' ? 30 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 8);
  const top = size === 'large' ? 50 : Math.max(n, 2 + Math.floor(rand() * 12));
  if (rand() < 0.4) return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
  // Mostly increasing: a strictly increasing pick from 1..top with a few positions overwritten.
  const pool = Array.from({ length: top }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const nums = pool.slice(0, n).sort((a, b) => a - b);
  const changes = Math.floor(rand() * 4);
  for (let c = 0; c < changes; c++) nums[Math.floor(rand() * n)] = 1 + Math.floor(rand() * top);
  return [nums];
}
